/**
 * The chart numbers for a rim variant: no hub logic, no side mapping.
 * @param {string|number} rimVariantId  digits, or a gid://shopify/ProductVariant/<digits>
 * @returns {null|{ source: 'i9-chart', row: object, driveColumn: number, nonDriveColumn: number, variantTitle: string, borrowed?: boolean, storeErd?: number, estimated?: { erd: number, gap: number, method: string } }}
 */
export function chartLengthsForRim(rimVariantId) {
  const id = String(rimVariantId == null ? '' : rimVariantId).replace(/^.*\//, '');
  if (!Object.prototype.hasOwnProperty.call(RIM_VARIANT_MAP, id)) return null;
  const e = RIM_VARIANT_MAP[id], row = CHART_ROWS[e.row];
  return { source: 'i9-chart', row, driveColumn: e.estimated ? e.estimated.drive : row.driveColumn, nonDriveColumn: e.estimated ? e.estimated.nonDrive : row.nonDriveColumn, variantTitle: e.title, ...(e.estimated ? { estimated: { erd: e.estimated.erd, gap: e.estimated.gap, method: e.estimated.method } } : {}), ...(e.borrowed ? { borrowed: true } : {}), ...(e.borrowedFrom ? { borrowedFrom: e.borrowedFrom } : {}), ...(e.storeErd ? { storeErd: e.storeErd } : {}) };
}
